INSERT INTO property_categories (code, name, fields, required, filters, scoring_profile, typical_risks, legal_checks, comparable_keys, sort) VALUES ('residential', '{"ru":"Жилая","it":"Residenziale","en":"Residential"}', '["area_m2","condition","year_built","energy_class","floor","floors_total","rooms","bedrooms","bathrooms","elevator","balcony_terrace","garden","parking_included","sea_view","furnished"]', '["area_m2"]', '["price","price_m2","net_yield","score","area_m2","rooms","condition","sea_view"]', 'residential', '["Ограничения краткосрочной аренды в коммуне","Расходы кондоминиума и предстоящие спецсборы","Несоответствие кадастра фактической планировке","Сезонность спроса в курортных зонах"]', '["Соответствие кадастровой и градостроительной документации (conformità urbanistica/catastale)","Отсутствие ипотек и обременений","Долги кондоминиума","Сертификат энергоэффективности"]', '["type","area_m2","rooms","condition","geohash6"]', 0);
INSERT INTO property_categories (code, name, fields, required, filters, scoring_profile, typical_risks, legal_checks, comparable_keys, sort) VALUES ('commercial', '{"ru":"Коммерческая","it":"Commerciale","en":"Commercial"}', '["area_m2","condition","year_built","energy_class","floor","frontage_m","shop_windows","ceiling_height_m","tenanted","lease_end","permitted_use"]', '["area_m2"]', '["price","price_m2","net_yield","score","area_m2","tenanted"]', 'commercial', '["Вакантность после ухода арендатора","Зависимость от одного арендатора","Разрешённое использование не подходит под нужный бизнес","Падение трафика на улице"]', '["Категория кадастра и разрешённое использование","Действующие договоры аренды и их условия","Санитарные/пожарные разрешения для общепита и медицины"]', '["type","area_m2","tenanted","geohash6"]', 1);
INSERT INTO property_categories (code, name, fields, required, filters, scoring_profile, typical_risks, legal_checks, comparable_keys, sort) VALUES ('industrial', '{"ru":"Промышленная и складская","it":"Industriale e logistica","en":"Industrial & logistics"}', '["area_m2","condition","year_built","energy_class","ceiling_height_m","loading_docks","truck_access","power_kw","fire_certificate","yard_m2","office_m2","tenanted","lease_end","permitted_use"]', '["area_m2"]', '["price","price_m2","net_yield","score","area_m2","ceiling_height_m","truck_access","tenanted"]', 'industrial', '["Загрязнение грунта","Недостаточная электрическая мощность","Устаревшие пожарные системы","Удалённость от магистралей"]', '["Экологические ограничения и история использования","Пожарный сертификат (CPI)","Разрешённое использование"]', '["type","area_m2","ceiling_height_m","geohash5"]', 2);
INSERT INTO property_categories (code, name, fields, required, filters, scoring_profile, typical_risks, legal_checks, comparable_keys, sort) VALUES ('parking', '{"ru":"Гаражи и парковки","it":"Box e posti auto","en":"Garages & parking"}', '["area_m2","condition","spaces","covered","width_m","length_m","ev_charger","separate_title","access_type","floor"]', '[]', '["price","price_m2","net_yield","score","spaces","covered","separate_title"]', 'parking', '["Нет отдельного объекта права — продажа только с квартирой (pertinenza)","Низкий локальный спрос","Узкий въезд, место не подходит для больших машин","Затопление подземных уровней"]', '["Самостоятельный кадастровый номер","Ограничения на продажу/аренду не жителям (vincolo pertinenziale)","Правила кондоминиума"]', '["type","covered","geohash6"]', 3);
INSERT INTO property_categories (code, name, fields, required, filters, scoring_profile, typical_risks, legal_checks, comparable_keys, sort) VALUES ('land', '{"ru":"Земельные участки","it":"Terreni","en":"Land"}', '["land_area_m2","zoning","buildable_m3","road_access","utilities_available","easements","slope","irrigation","trees"]', '["land_area_m2"]', '["price","land_area_m2","road_access","zoning","score"]', 'land', '["Застройка не разрешена или не подтверждена","Гидрогеологические и оползневые ограничения","Ландшафтные и природоохранные ограничения","Нет подъезда / коммуникаций"]', '["Справка о градостроительном назначении (CDU)","Сервитуты и права проезда","Право преимущественной покупки соседей-аграриев (prelazione agraria)","Природоохранные и гидрогеологические ограничения"]', '["type","land_area_m2","zoning","geohash5"]', 4);
INSERT INTO property_categories (code, name, fields, required, filters, scoring_profile, typical_risks, legal_checks, comparable_keys, sort) VALUES ('hospitality', '{"ru":"Туристическая","it":"Ricettivo","en":"Hospitality"}', '["area_m2","condition","year_built","energy_class","guest_rooms","beds","pitches","licence","seasonality","restaurant","pool","sea_view"]', '["area_m2"]', '["price","price_m2","net_yield","score","guest_rooms","licence","seasonality"]', 'hospitality', '["Сезонность и зависимость от туристического потока","Высокие расходы на персонал","Зависимость от комиссий платформ бронирования","Лицензия не переходит к покупателю"]', '["Действующие лицензии и классификация","Передаваемость лицензии","Пожарные и санитарные требования","Ограничения туристической аренды в регионе"]', '["type","guest_rooms","geohash5"]', 5);
